from hermes_tools import terminal
cmd = r'''python3 - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
wd=wb['Data']
print('Data all non-empty cells:')
for row in wd.iter_rows():
    non=[]
    for cell in row:
        if cell.value is not None:
            non.append(f'{cell.coordinate}={cell.value!r}')
    if non:
        print('; '.join(non))
print('\nCells equal years 2018-2022:')
for row in wd.iter_rows():
    for cell in row:
        if cell.value in [2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022']:
            print(cell.coordinate, repr(cell.value))
PY'''
res=terminal(cmd, timeout=600, workdir='/root')
print(res['output'])
print('exit_code', res['exit_code'])
